export const REFUSAL_EMITTERS: readonly RefusalEmitter[] = [{"origin":"the ZIFFER API","what":"the names the public API answers with, under `pub mod error_name`","names":["AdmissionUnavailable","ApiKeyUnknown","DecisionUnknown","FeedbackMalformed","FeedbackRateLimited","FeedbackTooLarge","FeedbackUnavailable","GatewayUnavailable","ListQueryMalformed","ProposalMalformed","QueueFull","RateLimited","TenantMismatch"]},{"origin":"the Policy Engine","what":"the rules the Policy Engine decides under, which the console and your audit chain name","names":["8.4-1","8.4-12","8.4-3","8.4-4","8.4-5","8.4-6","AT-4","B-6","CP-2","DP-37","DP-58","DP-59","DP-90","DR-19","PB-1","PR-1","WE-6"]},{"origin":"the Policy Engine, on an approval","what":"the clause ids an attestation is refused under","names":["9.3-7b-i","AB-1","AQ-3","AT-1","AT-2","AT-5","AT-9","DP-37"]},{"origin":"the decision API","what":"the refusal categories a decision's `refusal_category` carries","names":["PolicyBasisMoved","PolicyRefused","ProposalMalformed","RateBounded"]}];
